const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(data[0], 10);

function toCents(s) {
  const parts = s.split('.');
  const intPart = parts[0];
  let decPart = parts[1] || '';
  decPart = (decPart + '00').slice(0, 2);
  return parseInt(intPart, 10) * 100 + parseInt(decPart, 10);
}

let idx = 1;
let bestCents = null;
let bestG = 1;

for (let i = 0; i < n; i++) {
  const pCents = toCents(data[idx++]);
  const g = parseInt(data[idx++], 10);

  if (bestCents === null || pCents * bestG < bestCents * g) {
    bestCents = pCents;
    bestG = g;
  }
}

const roundedCents = Math.round(bestCents * 1000 / bestG);
const intPart = Math.floor(roundedCents / 100);
const decPart = (roundedCents % 100).toString().padStart(2, '0');

console.log(`${intPart}.${decPart}`);
